import{b as o,O as r,g as a,j as p}from"./chunks/framework.DSt9LnBW.js";const g=JSON.parse('{"title":"提问的智慧，先让问题值得被回答","description":"前阵子有一轮版本回归。提测第一天，一位测试同学发现附件传不上去，在群里 @ 负责这块的开发：在吗？附件上传有点问题，你看下。开发回了个\\"在\\"，然后等了七分钟。七分钟后，测试同学发过去一张截图：进度条停在 100%，弹窗里只有一行红字——上传失败。没有用例编号，没有构建号，也没有失败时的接口返回。","frontmatter":{"date":"2026-11-19T00:00:00.000Z","tags":["互联网","沟通","职业生涯"],"sidebar":false,"pageClass":"blog-post","prev":false,"next":false,"lastUpdated":false},"headers":[],"relativePath":"blog/internet-years/how-to-ask-questions-smart-way/index.md","filePath":"个人博客/在互联网的那些年/5.提问的智慧，先让问题值得被回答.md","lastUpdated":1795105189000}'),e={name:"blog/internet-years/how-to-ask-questions-smart-way/index.md"};function l(s,t,n,d,u,i){return r(),a("div",null,[...t[0]||(t[0]=[p('<h1 id="提问的智慧-先让问题值得被回答" tabindex="-1">提问的智慧，先让问题值得被回答 <a class="header-anchor" href="#提问的智慧-先让问题值得被回答" aria-label="Permalink to &quot;提问的智慧，先让问题值得被回答&quot;">​</a></h1><p>前阵子有一轮版本回归。提测第一天，一位测试同学发现附件传不上去，在群里 @ 负责这块的开发：</p><blockquote><p>在吗？附件上传有点问题，你看下。</p></blockquote><p>开发回了个&quot;在&quot;，然后等了七分钟。</p><p>七分钟后，测试同学发过去一张截图：进度条停在 100%，弹窗里只有一行红字——<code>上传失败</code>。没有用例编号，没有构建号，也没有失败时的接口返回。</p><p>开发又问：哪个环境？哪个版本？传的什么文件、多大？从哪一步开始失败的？</p><p>又过了五分钟，测试同学才补了一句：&quot;就是传一个 PDF，进度条走完了就报失败。&quot;</p><p>来回了四轮，开发才拿到足够定位问题的信息：测试环境、被测版本、文件类型和大小、复现步骤、接口返回和日志。</p><p><strong>这件事真正的问题不在技术，而在没有人意识到：&quot;提问&quot;本身是一件需要交付信息的事。</strong></p><p>那天收工前我想到一篇很老的文档——《提问的智慧》（How To Ask Questions The Smart Way）。它写于二十多年前的邮件列表时代，讲的东西放到今天的工单、群聊、AI 对话框里，一个字都没过时。</p><p>这篇就聊聊它：为什么&quot;在吗&quot;是最贵的一句话，以及一个值得被回答的问题长什么样。</p><h2 id="一、-在吗-为什么是最贵的一句话" tabindex="-1">一、&quot;在吗&quot;为什么是最贵的一句话 <a class="header-anchor" href="#一、-在吗-为什么是最贵的一句话" aria-label="Permalink to &quot;一、&quot;在吗&quot;为什么是最贵的一句话&quot;">​</a></h2><p>&quot;在吗&quot;看起来只是打招呼，实际上它做了一件很具体的事：<strong>把沟通的启动成本，转嫁给了对方。</strong></p><p>在同步聊天里，它意味着对方放下手里的活等你；在异步的工单和论坛里，它意味着一个问题被硬生生拆成两轮——先确认你在不在，再确认你要问什么。</p><p>一个问题本来可以一次发完。你偏偏要分两次，第二次还得等对方重新捡起上下文。</p><p>很多人觉得这是礼貌。其实真正的礼貌是：<strong>让对方在你发出消息的那一刻，就能开始思考。</strong></p><p>提问不是打招呼，提问是一次信息交付。交付得完整，对方接得住；交付得残缺，对方得先帮你补货。</p><p>一句更直白的话：</p><blockquote><p><strong>你省下的描述时间，会成倍地变成对方追问的时间。</strong></p></blockquote><h2 id="二、提问之前-先自己走一遍" tabindex="-1">二、提问之前，先自己走一遍 <a class="header-anchor" href="#二、提问之前-先自己走一遍" aria-label="Permalink to &quot;二、提问之前，先自己走一遍&quot;">​</a></h2><p>原文列了七条：搜旧帖、上网搜、读手册、读 FAQ、自己试验、问身边的朋友、读源码。</p><p>看起来是七件事，其实是四层：</p><table tabindex="0"><thead><tr><th>层次</th><th>在查什么</th><th>典型动作</th></tr></thead><tbody><tr><td>有没有人问过</td><td>这个问题是不是已经被回答过一百遍</td><td>搜旧帖、搜搜索引擎、搜 issue</td></tr><tr><td>有没有人写过</td><td>官方是不是已经写了答案</td><td>读文档、读 FAQ、读 changelog</td></tr><tr><td>我能不能自己验证</td><td>是不是我环境、数据或操作的问题</td><td>最小用例、换环境、看日志</td></tr><tr><td>身边有没有人知道</td><td>是不是本地经验能解决</td><td>问同事、问朋友、读源码</td></tr></tbody></table><p>这四层不是走形式。<strong>每走一层，你手里的信息就多一分，问题的质量就高一截。</strong></p><p>举个最常见的例子：一条自动化用例在 CI 上偶发失败，把报错原文扔进搜索框，第一条往往就是测试框架的已知 issue，里面写着&quot;升级到 x.y.z 版本即可&quot;。这件事花三十秒，却能让一个原本要等两小时的问题当场结束。</p><p>我自己有个判断标准：<strong>当我准备开口问人时，我应该已经走到&quot;最后一公里&quot;——不是第一步就卡住，而是该查的都查了，剩下的是只有人能回答的判断。</strong></p><p>这条标准一旦建立，你会发现一个变化：你问出去的问题变少了，但被回答的比例变高了。因为回答的人能感觉到，你不是来碰运气的。</p><h2 id="三、这是一笔成本账-不是道德账" tabindex="-1">三、这是一笔成本账，不是道德账 <a class="header-anchor" href="#三、这是一笔成本账-不是道德账" aria-label="Permalink to &quot;三、这是一笔成本账，不是道德账&quot;">​</a></h2><p>为什么答主会烦&quot;伸手党&quot;？很多人把它理解成态度问题，其实它是经济问题。</p><table tabindex="0"><thead><tr><th></th><th>提问者</th><th>回答者</th></tr></thead><tbody><tr><td>付出</td><td>一次描述</td><td>一次阅读 + 一次追问 + 一次回答</td></tr><tr><td>重复次数</td><td>1 次</td><td>同一个问题可能被问 N 次</td></tr><tr><td>收益</td><td>自己的问题被解决</td><td>没有直接收益，多数是义务劳动</td></tr></tbody></table><p>论坛、开源社区、技术群里的答主，绝大多数是志愿者。他们没有义务，只有意愿。而<strong>能搜到答案的问题，本质上是在消耗一份公共资源</strong>——这份资源有限，用一点少一点。</p><p>所以那些社区规矩看着凶，比如&quot;提问前先搜索&quot;&quot;不要贴大段无关日志&quot;&quot;标题写清楚&quot;，背后都有同一句潜台词：</p><blockquote><p><strong>请把回答者的时间，花在只有人能回答的地方。</strong></p></blockquote><p>这不是要求提问者卑微，恰恰相反——<strong>认真提问，是把对方当成值得认真对待的专家。</strong></p><h2 id="四、好标题-目标-差异" tabindex="-1">四、好标题：目标 - 差异 <a class="header-anchor" href="#四、好标题-目标-差异" aria-label="Permalink to &quot;四、好标题：目标 - 差异&quot;">​</a></h2><p>原文给了一个很实用的格式：<strong>目标 - 差异</strong>。</p><ul><li><strong>目标</strong>：我在试图做什么，用的是哪个东西、哪个版本</li><li><strong>差异</strong>：哪里和期望不一致，报了什么错</li></ul><p>对比一下：</p><table tabindex="0"><thead><tr><th>差标题</th><th>为什么差</th></tr></thead><tbody><tr><td>求助！！</td><td>没有信息，只有情绪</td></tr><tr><td>有人吗</td><td>不是问题，是敲门</td></tr><tr><td>登录失败</td><td>哪个版本、什么账号、哪一步，全没有</td></tr><tr><td>导出功能有问题</td><td>连&quot;期望什么、实际什么&quot;都没说</td></tr><tr><td>急急急，在线等</td><td>把紧迫感当成了信息</td></tr></tbody></table><p>好的标题长这样：</p><blockquote><p>回归环境 v2.8.0，供应商账号登录提示&quot;登录失败&quot;，个人账号正常，昨天同版本还是好的</p></blockquote><p>这句话里已经有：环境、版本、账号类型、现象、对比条件和时间线。懂行的人扫一眼就知道该往哪想。</p><p>还有一层很多人没意识到：<strong>标题是写给未来的搜索者写的。</strong></p><p>一个论坛帖子发出去，三年后还会有陌生人搜到它。标题写得清楚，它就变成一份能被复用的档案；标题写成&quot;求助&quot;，它就变成一条谁也检索不到的死数据。</p><p>这大概就是&quot;在互联网的那些年&quot;里最朴素的一条规律：<strong>你今天怎么提问，决定了明天别人能不能搜到答案。</strong></p><h2 id="五、一个完整的问题长什么样" tabindex="-1">五、一个完整的问题长什么样 <a class="header-anchor" href="#五、一个完整的问题长什么样" aria-label="Permalink to &quot;五、一个完整的问题长什么样&quot;">​</a></h2><p>把前面几条拼起来，一个合格的提问至少包含六样东西：</p><ol><li><strong>环境</strong>：测试环境、被测版本、浏览器或客户端版本、账号类型、关键数据配置</li><li><strong>复现步骤</strong>：从哪一步开始，点了什么，用了什么测试数据，做了几次</li><li><strong>预期结果</strong>：你认为应该发生什么</li><li><strong>实际结果</strong>：实际发生了什么，完整报错信息或接口返回是什么</li><li><strong>已尝试</strong>：你试过哪些排查，为什么排除了</li><li><strong>最小复现</strong>：能独立跑起来的最小用例、最小数据集、最小配置</li></ol><p>第 5 条最容易被忽略，也最值钱。</p><p>&quot;我刷新了一下就好了&quot;&quot;我重试了一次还是不行&quot;这种不算有效尝试。有效的是：&quot;我换 Chrome 和 Safari 都能复现，换成普通个人账号就正常；把账号的供应商资质状态改回上周的值也能正常，所以问题大概率在资质校验逻辑上。&quot;</p><p><strong>这句话直接替回答者省掉了一轮排查。</strong></p><p>第 6 条则决定了对方愿不愿意动手。一份能三分钟照着做一遍的最小用例、配一份能直接导入的最小数据集，比十页截图都有用——因为它可以被验证，而截图只能被相信。</p><p>我现在的习惯是先写这六项，再决定要不要发。很多时候写到第四项，答案自己就出来了。</p><h2 id="六、别问-xy-问题" tabindex="-1">六、别问 XY 问题 <a class="header-anchor" href="#六、别问-xy-问题" aria-label="Permalink to &quot;六、别问 XY 问题&quot;">​</a></h2><p>这是原文里我觉得最锋利的一个观点：<strong>描述目标，而不是过程</strong>——后来社区把这类情况叫作&quot;XY 问题&quot;。</p><p>你想解决 X，自己想到了一个方案 Y，结果卡在 Y 上，于是你去问 Y。</p><p>举个真实场景：</p><ul><li>真实目标 X：验证导出 10 万行数据能不能在 30 分钟内正常完成</li><li>自己想的方案 Y：先写个脚本造 10 万行测试数据</li><li>卡住的点：造数脚本跑到一半内存溢出</li><li>提出的问题：<strong>&quot;造数脚本内存溢出怎么调？&quot;</strong></li></ul><p>如果只回答这个问题，你可能把脚本改成流式写入、分批提交，调得很精巧，结果发现导出任务照样失败——因为它压根不是数据量的问题，而是分页参数上限写死了 5000。</p><p><strong>Y 从头到尾都不是问题所在。</strong></p><p>正确的方式是先说目标，再说你选的方案和理由：</p><blockquote><p>我要验证导出 10 万行是否正常，手上没有这么大的一份数据，就写了个脚本自己造，跑到一半 OOM。我猜是数据量太大，准备改成流式写入，但不确定方向对不对。导出任务在 10 万行这个量级有没有已知限制？有没有更省事的造数办法？</p></blockquote><p>这样回答者才有机会告诉你：&quot;别折腾脚本了，用测试环境自带的批量造数接口；导出失败是分页参数写死 5000，跟数据量没关系。&quot;</p><p>还有一个同类的坏习惯：<strong>&quot;有人会写 pytest 吗？&quot;</strong></p><p>这不是提问，这是点名。想问就直说：</p><blockquote><p>有个 pytest 用例在 Jenkins 上偶发失败，本地连跑十次全过，想确认一下是不是 pytest-xdist 并发执行导致的用例间数据污染。</p></blockquote><p><strong>&quot;能不能问&quot;这一步，永远是多余的。</strong></p><h2 id="七、把问题写出来-答案常常自己出现" tabindex="-1">七、把问题写出来，答案常常自己出现 <a class="header-anchor" href="#七、把问题写出来-答案常常自己出现" aria-label="Permalink to &quot;七、把问题写出来，答案常常自己出现&quot;">​</a></h2><p>这是提问最反直觉的一个副作用：<strong>很多问题在写到一半的时候，就被自己解决了。</strong></p><p>因为写下来的过程，会强迫你把脑子里那些含糊的东西一个个摊开：</p><ul><li>&quot;这个用例跑不过&quot; → 具体哪一行断言没过？</li><li>&quot;昨天还好好的&quot; → 昨天到今天，环境、版本、测试数据哪个变了？</li><li>&quot;我这边能过，你那边不行&quot; → 两边到底差了什么？</li></ul><p>这三句话问完，答案往往在最后一句里。</p><p>工程师管这个叫&quot;小黄鸭调试法&quot;——对着桌上一只橡皮鸭，把问题从头到尾讲一遍。鸭子什么都不用做，你的大脑会自己补齐逻辑。</p><p>所以我现在的习惯是：<strong>先把问题按六要素写完，再决定要不要发出去。</strong></p><p>十次里有三次，写到&quot;已尝试&quot;那一段，就发现方向错了。</p><p>如果还没解决，那就再走一遍自检清单：</p><ol><li>我搜过报错的原文了吗？</li><li>我读过相关文档和 changelog 了吗？</li><li>我能不能用最小的用例和数据复现它？</li><li>我试过的方案，是&quot;试了没用&quot;，还是&quot;试了但没验证&quot;？</li><li>我的问题里，有没有一句是我以为对方知道、但其实没说的？</li></ol><p>第五个最要紧。<strong>默认对方什么都不知道，是提问者最有用的一个假设。</strong></p><h2 id="八、stack-overflow-的边界" tabindex="-1">八、Stack Overflow 的边界 <a class="header-anchor" href="#八、stack-overflow-的边界" aria-label="Permalink to &quot;八、Stack Overflow 的边界&quot;">​</a></h2><p>原文特别提到：Stack Overflow 是问<strong>编程</strong>问题的地方。</p><p>这句话今天看依然准确，但它背后还有一层筛选逻辑——不是&quot;编程问题就能问&quot;，而是&quot;<strong>能被回答的问题</strong>才适合放在那里&quot;。</p><table tabindex="0"><thead><tr><th>适合</th><th>不适合</th></tr></thead><tbody><tr><td>可复现的代码问题</td><td>主观讨论、选型争论</td></tr><tr><td>有明确对错</td><td>&quot;哪个框架最好&quot;</td></tr><tr><td>不依赖私有环境</td><td>需要内部账号才能复现</td></tr><tr><td>对后来者有复用价值</td><td>一次性的求助、找人代做</td></tr></tbody></table><p>社区那些严格的关闭理由——重复、缺乏最小示例、不属于编程范围——本质上都在维护一件事：<strong>这个问题的答案，值不值得被永久保存。</strong></p><p>这也是提问这件事最容易被忽略的长期价值。你不是在索取一个答案，你是在给互联网留一条记录。</p><h2 id="九、从邮件列表到-ai-方法没变-门槛变低了" tabindex="-1">九、从邮件列表到 AI：方法没变，门槛变低了 <a class="header-anchor" href="#九、从邮件列表到-ai-方法没变-门槛变低了" aria-label="Permalink to &quot;九、从邮件列表到 AI：方法没变，门槛变低了&quot;">​</a></h2><p>《提问的智慧》诞生在邮件列表和新闻组的年代。那时候发一封邮件，要等几个小时才有回音，所以人们会认真写。</p><p>后来是论坛、Stack Overflow、技术群。现在多了一个对象：AI。</p><p>有意思的是，<strong>AI 没有让&quot;会提问&quot;这件事变得不重要，反而让它变得更值钱。</strong></p><ul><li>以前描述不清，答主会追问你三轮</li><li>现在描述不清，AI 会一本正经地给你一个不对的答案，然后你继续追问，来回十轮，越走越偏</li></ul><p>一个很典型的对比：</p><p><strong>差的问法</strong>：&quot;我这条用例失败了，怎么修？&quot;</p><p><strong>好的问法</strong>：&quot;pytest 用例在 Jenkins 并行任务里偶发失败，本地单跑十次全过，报错是 <code>TimeoutError: waiting for selector &#39;#submit&#39;</code>，失败集中在构建机负载高的时段。我已经确认元素不是懒加载的。这更像并发冲突还是等待策略的问题？&quot;</p><p>第二种问法，一次就能命中。因为<strong>你把 AI 当成一个需要上下文的专家，而不是一个会猜心的算命先生。</strong></p><p>换个角度说：AI 把&quot;自查&quot;这一步变得极其便宜——你可以让它在几秒内帮你读完文档、搜索 issue、生成最小示例。但前提是，<strong>你得知道该让它查什么。</strong></p><p>而这，恰恰还是那套老方法。</p><h2 id="十、被拒绝了-然后呢" tabindex="-1">十、被拒绝了，然后呢 <a class="header-anchor" href="#十、被拒绝了-然后呢" aria-label="Permalink to &quot;十、被拒绝了，然后呢&quot;">​</a></h2><p>刚进这行的时候，我在一个论坛问过一个现在想起来很脸红的问题，被回了一句：<strong>RTFM</strong>（Read The F***ing Manual）。</p><p>当时觉得是羞辱。后来自己开始回答别人的问题，才明白那句话的意思通常是：<strong>这个问题答案就在文档第一页，而我已经是这周第五次回答它了。</strong></p><p>遇到这种回复，最没用的反应是争论态度，最有用的反应是回去把文档读了，然后回来补一句：</p><blockquote><p>抱歉，是我没看文档。问题的原因是 xxx，解决办法是 xxx，留给后面搜到的人。</p></blockquote><p>这一句，比一句谢谢有价值得多。</p><p>因为它补上了提问的最后一环：<strong>闭环。</strong></p><ul><li>问题解决了，回帖说明是怎么解决的</li><li>标题加上&quot;已解决&quot;</li><li>如果是文档缺陷，顺手提一个 issue</li></ul><p>论坛能活下来，靠的就是这个循环：今天被回答的人，明天变成回答的人。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>《提问的智慧》写了二十多年，核心其实就一句话：</p><blockquote><p><strong>提问的质量，决定了你被帮助的质量。</strong></p></blockquote><p>五个可以带走的：</p><ol><li><strong>别问&quot;在吗&quot;。</strong> 提问是一次信息交付，不是敲门。让对方在读到你消息的第一秒就能开始思考。</li><li><strong>先自查，再开口。</strong> 搜旧帖、搜引擎、读文档、自己试验。自查不是礼貌，是成本最低的排查路径。</li><li><strong>标题用&quot;目标 - 差异&quot;。</strong> 而且记住：标题是写给未来搜到这个帖子的人写的。</li><li><strong>给全六要素，别问 XY。</strong> 环境、步骤、预期、实际、已尝试、最小复现。想解决 X，就直接说 X。</li><li><strong>记得闭环。</strong> 解决了就回来说清楚怎么解决的——你今天留下的记录，就是别人明天的答案。</li></ol><p>最后回到那轮回归。后来复盘时，开发说过一句：&quot;我以为你至少会带上环境和复现步骤。&quot;</p><p>测试同学说：&quot;我以为你会问。&quot;</p><p>两句话都很客气，信息却一句也没交出去。这大概就是提问这件事最日常的样子——不是没人愿意答，是问题还没走到能被回答的那一步。</p>',112)])])}const h=o(e,[["render",l]]);export{g as __pageData,h as default};
